//! Offline gate over the coverage sets (openspec/changes/add-coverage-configuration).
//!
//! Every set under `tests/fixtures/coverage/<platform>/<set>/` was generated by
//! `tools/coverage/generate.py` and proven by `tools/coverage/native_round_trip.py`
//! on the native platform. This test exports each set's `.cf` without the
//! platform and compares every variant's files with the native ones. A variant
//! listed in the set's `baseline.json` must stay equal; any other variant that
//! becomes equal is reported so it can join the baseline.

use std::{
    collections::{BTreeMap, BTreeSet},
    fmt::Write as _,
    fs,
    path::{Path, PathBuf},
    process::Command,
    sync::atomic::{AtomicUsize, Ordering},
    time::{SystemTime, UNIX_EPOCH},
};

use serde_json::Value;
use sha2::{Digest, Sha256};

const DUMP_INFO: &str = "ConfigDumpInfo.xml";

struct TempDirectory(PathBuf);

impl TempDirectory {
    fn new() -> Self {
        static SEQUENCE: AtomicUsize = AtomicUsize::new(0);
        let nonce = format!(
            "{}-{}",
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos(),
            SEQUENCE.fetch_add(1, Ordering::Relaxed)
        );
        let path =
            std::env::temp_dir().join(format!("ibcmd-rs-coverage-{}-{nonce}", std::process::id()));
        fs::create_dir(&path).unwrap();
        Self(path)
    }
}

impl Drop for TempDirectory {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn decode_base64(source: &[u8]) -> Vec<u8> {
    let mut output = Vec::new();
    let (mut buffer, mut bits) = (0_u32, 0_u8);
    for &byte in source {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' | b'\r' | b'\n' | b' ' => continue,
            _ => panic!("invalid Base64 byte 0x{byte:02x}"),
        };
        buffer = (buffer << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            output.push(((buffer >> bits) & 0xff) as u8);
            buffer &= (1_u32 << bits) - 1;
        }
    }
    output
}

/// File names as the platform composes them: `й`/`ё` may come decomposed from
/// some file systems.
fn compose(path: &str) -> String {
    path.replace("и\u{306}", "й")
        .replace("И\u{306}", "Й")
        .replace("е\u{308}", "ё")
        .replace("Е\u{308}", "Ё")
}

fn read_tree(root: &Path) -> BTreeMap<String, Vec<u8>> {
    fn visit(root: &Path, current: &Path, files: &mut BTreeMap<String, Vec<u8>>) {
        for entry in fs::read_dir(current).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                visit(root, &path, files);
            } else if path.file_name().is_some_and(|name| name != DUMP_INFO) {
                let relative = path
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                files.insert(compose(&relative), fs::read(&path).unwrap());
            }
        }
    }
    let mut files = BTreeMap::new();
    if root.is_dir() {
        visit(root, root, &mut files);
    }
    files
}

fn inputs_digest(set: &Path) -> String {
    let mut files = Vec::new();
    fn visit(set: &Path, current: &Path, files: &mut Vec<(String, Vec<u8>)>) {
        for entry in fs::read_dir(current).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                visit(set, &path, files);
            } else {
                let relative = path
                    .strip_prefix(set)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                files.push((compose(&relative), fs::read(&path).unwrap()));
            }
        }
    }
    // A combined set has no inputs of its own (the digest of nothing).
    if set.join("input").is_dir() {
        visit(set, &set.join("input"), &mut files);
    }
    files.sort();
    let mut digest = Sha256::new();
    for (path, bytes) in files {
        digest.update(path.as_bytes());
        digest.update([0]);
        digest.update(&bytes);
    }
    format!("{:x}", digest.finalize())
}

/// Every directory under `tests/fixtures/coverage` with a `manifest.json`:
/// `<platform>/<class>/`, `<platform>/external/<set>/`, `<platform>/extensions/<set>/`.
fn coverage_sets() -> Vec<PathBuf> {
    fn visit(dir: &Path, sets: &mut Vec<PathBuf>) {
        if dir.join("manifest.json").is_file() {
            sets.push(dir.to_path_buf());
            return;
        }
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                visit(&path, sets);
            }
        }
    }
    let mut sets = Vec::new();
    visit(
        &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/coverage"),
        &mut sets,
    );
    sets.sort();
    sets
}

#[derive(Debug, PartialEq, Eq)]
enum Verdict {
    Equal,
    Different(String),
    Refused,
    PlatformRefused,
}

struct Measured {
    report: String,
    regressions: Vec<String>,
}

/// Exports `file` with ibcmd-rs into `out`; the tree, or the command's last
/// stderr line when it refuses.
fn cf_export(
    file: &Path,
    out: &Path,
    source_version: &str,
) -> Result<BTreeMap<String, Vec<u8>>, String> {
    let export = Command::new(env!("CARGO_BIN_EXE_ibcmd-rs"))
        .args(["cf", "export"])
        .arg(file)
        .arg(out)
        .args(["--source-version", source_version])
        .env("PATH", "")
        .output()
        .unwrap();
    if export.status.success() {
        return Ok(read_tree(out));
    }
    // The command reports its refusal as JSON on one of its streams.
    let report = [&export.stdout, &export.stderr]
        .into_iter()
        .find_map(|stream| {
            let text = String::from_utf8_lossy(stream);
            serde_json::from_str::<Value>(&text[text.find('{')?..]).ok()
        });
    let first = report
        .as_ref()
        .and_then(|report| report["errors"].get(0))
        .map(|error| {
            format!(
                "{}: {}",
                error["code"].as_str().unwrap_or("error"),
                error["message"].as_str().unwrap_or_default()
            )
        });
    Err(first.unwrap_or_else(|| {
        String::from_utf8_lossy(&export.stderr)
            .lines()
            .last()
            .unwrap_or_default()
            .to_owned()
    }))
}

/// The verdict of one variant: its native files against ours, plus any file
/// we write for it that the platform does not.
fn compare(
    variant: &Value,
    native: &BTreeMap<String, Vec<u8>>,
    ours: &BTreeMap<String, Vec<u8>>,
    own: &[String],
    claimed: &mut BTreeSet<String>,
    name: &str,
) -> Verdict {
    let mut verdict = Verdict::Equal;
    let mut mine = BTreeSet::new();
    for file in variant["files"].as_array().unwrap() {
        let path = compose(file["path"].as_str().unwrap());
        claimed.insert(path.clone());
        mine.insert(path.clone());
        let expected = native
            .get(&path)
            .unwrap_or_else(|| panic!("{name}: native/{path} is missing"));
        assert_eq!(
            sha256_hex(expected),
            file["sha256"].as_str().unwrap(),
            "{name}: native/{path} does not match the manifest"
        );
        if ours.get(&path) != Some(expected) && verdict == Verdict::Equal {
            verdict = Verdict::Different(match ours.get(&path) {
                Some(actual) => {
                    format!("{path} ({} bytes, native {})", actual.len(), expected.len())
                }
                None => format!("{path} (not written)"),
            });
        }
    }
    if verdict == Verdict::Equal
        && let Some(extra) = ours.keys().find(|path| {
            !mine.contains(*path)
                && own.iter().any(|own| {
                    path.as_str() == format!("{own}.xml") || path.starts_with(&format!("{own}/"))
                })
        })
    {
        verdict = Verdict::Different(format!("{extra} (not written by the platform)"));
    }
    verdict
}

fn measure(set: &Path) -> Measured {
    let manifest: Value =
        serde_json::from_slice(&fs::read(set.join("manifest.json")).unwrap()).unwrap();
    let name = manifest["set"].as_str().unwrap();
    let source_version = manifest["evidence"]["source_version"].as_str().unwrap();
    let mut regressions = Vec::new();

    // The fixture is the one the platform proved.
    assert_eq!(
        inputs_digest(set),
        manifest["inputs_sha256"].as_str().unwrap(),
        "{name}: input/ differs from the inputs the set was proven from; rerun the native round trip"
    );
    // The combined set is made of the class sets beside it: it is current only
    // while their manifests are the ones it was built from.
    for source in manifest["sources"].as_array().into_iter().flatten() {
        let path = set
            .parent()
            .unwrap()
            .join(source["path"].as_str().unwrap())
            .join("manifest.json");
        assert_eq!(
            fs::read(&path)
                .map(|bytes| sha256_hex(&bytes))
                .ok()
                .as_deref(),
            source["manifest_sha256"].as_str(),
            "{name}: {} changed since the combined set was built; rerun tools/coverage/combine.py",
            path.display()
        );
    }
    let native = read_tree(&set.join("native"));
    let temp = TempDirectory::new();
    let mut claimed = BTreeSet::new();
    let mut verdicts = BTreeMap::new();
    let mut failure = None;

    let kind = manifest["kind"].as_str().unwrap_or("configuration");
    if matches!(kind, "external" | "extension") {
        // One file per variant, exported on its own. An external file's tree
        // is `<name>.xml` plus `<name>/`; an extension's is a configuration
        // tree, which the native side keeps under `<name>/`.
        for variant in manifest["variants"].as_array().unwrap() {
            let variant_name = variant["name"].as_str().unwrap().to_owned();
            if variant["status"] == "platform_refused" {
                verdicts.insert(variant_name, Verdict::PlatformRefused);
                continue;
            }
            let encoded = variant["file"]["path"].as_str().unwrap();
            let bytes = decode_base64(&fs::read(set.join(encoded)).unwrap());
            assert_eq!(
                sha256_hex(&bytes),
                variant["file"]["decoded_sha256"].as_str().unwrap(),
                "{name}: {encoded} does not match the manifest"
            );
            let file_name = Path::new(encoded).file_stem().unwrap();
            let file = temp.0.join(file_name);
            let out = temp.0.join(format!("{variant_name}-export"));
            fs::write(&file, &bytes).unwrap();
            let exported = cf_export(&file, &out, source_version).map(|ours| {
                if kind == "extension" {
                    ours.into_iter()
                        .map(|(path, bytes)| (format!("{variant_name}/{path}"), bytes))
                        .collect()
                } else {
                    ours
                }
            });
            let verdict = match exported {
                Ok(ours) => compare(
                    variant,
                    &native,
                    &ours,
                    &[variant_name.clone()],
                    &mut claimed,
                    name,
                ),
                Err(message) => {
                    failure.get_or_insert(message);
                    for path in variant["files"].as_array().unwrap() {
                        claimed.insert(compose(path["path"].as_str().unwrap()));
                    }
                    Verdict::Refused
                }
            };
            verdicts.insert(variant_name, verdict);
        }
    } else {
        let encoded = fs::read(set.join("configuration.cf.b64")).unwrap();
        let cf = decode_base64(&encoded);
        assert_eq!(
            sha256_hex(&cf),
            manifest["configuration_cf"]["decoded_sha256"]
                .as_str()
                .unwrap(),
            "{name}: configuration.cf.b64 does not match the manifest"
        );
        let cf_path = temp.0.join("set.cf");
        fs::write(&cf_path, &cf).unwrap();
        let ours = cf_export(&cf_path, &temp.0.join("export"), source_version);
        // A class set names its variants by object; the combined set names
        // them `<collection>/<object>` already.
        let collection = manifest["collection"].as_str();
        for variant in manifest["variants"].as_array().unwrap() {
            let variant_name = variant["name"].as_str().unwrap().to_owned();
            if variant["status"] == "platform_refused" {
                verdicts.insert(variant_name, Verdict::PlatformRefused);
                continue;
            }
            let own = match collection {
                Some(collection) => format!("{collection}/{variant_name}"),
                None => variant_name.clone(),
            };
            let verdict = match &ours {
                Ok(ours) => compare(variant, &native, ours, &[own], &mut claimed, name),
                Err(message) => {
                    failure.get_or_insert(message.clone());
                    for path in variant["files"].as_array().unwrap() {
                        claimed.insert(compose(path["path"].as_str().unwrap()));
                    }
                    Verdict::Refused
                }
            };
            verdicts.insert(variant_name, verdict);
        }
    }
    assert_eq!(
        native
            .keys()
            .filter(|path| !claimed.contains(*path))
            .count(),
        0,
        "{name}: native/ holds files no variant claims"
    );

    let baseline: BTreeSet<String> = fs::read(set.join("baseline.json"))
        .ok()
        .map(|bytes| serde_json::from_slice::<Value>(&bytes).unwrap())
        .map(|value| {
            value["equal"]
                .as_array()
                .unwrap()
                .iter()
                .map(|item| item.as_str().unwrap().to_owned())
                .collect()
        })
        .unwrap_or_default();

    let count =
        |wanted: fn(&Verdict) -> bool| verdicts.values().filter(|verdict| wanted(verdict)).count();
    let mut report = String::new();
    writeln!(
        report,
        "coverage {name}: generated {}, platform proven {}, platform refused {}, equal {}, different {}, refused by ibcmd-rs {}",
        verdicts.len(),
        verdicts.len() - count(|v| *v == Verdict::PlatformRefused),
        count(|v| *v == Verdict::PlatformRefused),
        count(|v| *v == Verdict::Equal),
        count(|v| matches!(v, Verdict::Different(_))),
        count(|v| *v == Verdict::Refused),
    )
    .unwrap();
    if let Some(message) = &failure {
        writeln!(report, "  cf export refused: {message}").unwrap();
    }
    for (variant, verdict) in &verdicts {
        let listed = baseline.contains(variant);
        match verdict {
            Verdict::Equal if !listed => {
                writeln!(report, "  newly equal (add to baseline.json): {variant}").unwrap()
            }
            Verdict::Different(first) => {
                writeln!(report, "  different: {variant}: {first}").unwrap();
                if listed {
                    regressions.push(format!("{name}: {variant} no longer equal: {first}"));
                }
            }
            Verdict::Refused if listed => {
                regressions.push(format!("{name}: {variant} no longer exported"))
            }
            _ => {}
        }
    }
    for variant in &baseline {
        if !verdicts.contains_key(variant) {
            regressions.push(format!(
                "{name}: baseline names {variant}, which the set does not have"
            ));
        }
    }
    Measured {
        report,
        regressions,
    }
}

#[test]
fn coverage_sets_hold_their_baseline() {
    let sets = coverage_sets();
    assert!(
        !sets.is_empty(),
        "no coverage set under tests/fixtures/coverage"
    );
    let mut regressions = Vec::new();
    for set in &sets {
        let measured = measure(set);
        print!("{}", measured.report);
        regressions.extend(measured.regressions);
    }
    assert!(
        regressions.is_empty(),
        "covered variants regressed:\n{}",
        regressions.join("\n")
    );
}

#[test]
fn variant_files_are_attributed_by_object() {
    // `Catalogs/CovX.xml` and `Catalogs/CovX/…` belong to CovX; everything
    // outside the collection belongs to the configuration itself.
    assert_eq!(
        compose("Languages/Русскии\u{306}.xml"),
        "Languages/Русский.xml"
    );
}
